<?php declare(strict_types=1); require_once __DIR__.'/../config/database.php'; $orders=db()->query('SELECT * FROM orders ORDER BY created_at DESC')->fetchAll(); function rupiah(int $v): string{return 'Rp'.number_format($v,0,',','.');} ?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Pesanan | @mencraft.id</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="../css/style.css"></head><body><main class="container section-space"><p class="eyebrow">ADMIN MENCRAFT</p><h1>Data Pesanan</h1><p class="text-muted">Data pesanan yang tersimpan di MySQL.</p><div class="content-card mt-4" style="overflow-x:auto"><table class="table align-middle"><thead><tr><th>Kode</th><th>Pelanggan</th><th>Pembayaran</th><th>Subtotal</th><th>Status</th><th>Waktu</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><strong><?=htmlspecialchars($o['order_code'])?></strong></td><td><?=htmlspecialchars($o['customer_name'])?><br><small><?=htmlspecialchars($o['customer_phone'])?></small></td><td><?=htmlspecialchars($o['payment_method'])?></td><td><?=rupiah((int)$o['subtotal'])?></td><td><?=htmlspecialchars($o['status'])?></td><td><?=htmlspecialchars($o['created_at'])?></td></tr><?php endforeach; ?><?php if(!$orders): ?><tr><td colspan="6" class="text-center text-muted">Belum ada pesanan.</td></tr><?php endif; ?></tbody></table></div><a href="../index.php" class="btn btn-outline-primary mt-3">Kembali ke Website</a></main></body></html>
